<?php
namespace OpenLMS\Controllers;

use OpenLMS\Core\Auth;
use OpenLMS\Core\Csrf;
use OpenLMS\Core\Database;
use OpenLMS\Policies\CoursePolicy;
use OpenLMS\Services\UploadService;

trait LessonLearningTrait
{
    public static function lesson(): void
    {
        Auth::requireAuth();
        $pdo=Database::connection();$user=Auth::user();$id=(int)($_GET['id']??0);$lesson=self::loadLesson($pdo,$id);if(!$lesson)self::notFoundOrDenied();$course=self::loadCourse($pdo,(int)$lesson['course_id']);if(!$course||!CoursePolicy::canViewCourse($course,$user))self::notFoundOrDenied();$canManage=CoursePolicy::canManage($course,$user);
        if(!$canManage && !CoursePolicy::lessonAvailableForStudent($lesson,(int)$user['id'])){http_response_code(403);render_page('Lesson locked','<div class="card empty-state"><h2>Lesson locked</h2><p>Complete the required prerequisite lessons or wait until the scheduled release time.</p><a class="btn" href="'.e(app_url('?r=course&id='.(int)$course['id'])).'">Back to course</a></div>');return;}
        $message=$error=null;

        if($_SERVER['REQUEST_METHOD']==='POST'){
            if(!Csrf::validate($_POST['_csrf']??null))$error='Invalid security token.';
            else{$action=(string)($_POST['action']??'');try{
                if($action==='update_lesson'&&$canManage){
                    $title=trim((string)($_POST['title']??''));if($title==='')throw new \RuntimeException('Lesson title is required.');$status=in_array((string)($_POST['status']??''),['draft','published','archived'],true)?(string)$_POST['status']:$lesson['status'];
                    $pdo->prepare('UPDATE lessons SET title=?,content=?,objectives=?,instructions=?,duration_minutes=?,status=?,release_at=?,updated_at=? WHERE id=?')->execute([$title,sanitize_rich_text((string)($_POST['content']??'')),trim((string)($_POST['objectives']??''))?:null,trim((string)($_POST['instructions']??''))?:null,self::positiveIntOrNull($_POST['duration_minutes']??null),$status,utc_datetime_from_input($_POST['release_at']??null),gmdate('Y-m-d H:i:s'),$id]);Auth::audit('lessons.update','Updated lesson '.$title,null,'lesson',$id);$message='Lesson saved.';$lesson=self::loadLesson($pdo,$id);
                }elseif($action==='upload_material'&&$canManage){[$ok,$result]=UploadService::storeLessonMaterial($id,$_FILES['material']??[]);if(!$ok)$error=(string)$result;else{$message='Learning material uploaded.';Auth::audit('materials.upload','Uploaded lesson material',null,'lesson',$id);}
                }elseif($action==='delete_material'&&$canManage){$mat=self::materialForLesson($pdo,(int)($_POST['material_id']??0),$id);if($mat){UploadService::deleteMaterial($mat);$message='Material removed.';Auth::audit('materials.delete','Deleted lesson material',null,'lesson',$id);}
                }elseif($action==='add_link'&&$canManage){$title=trim((string)($_POST['title']??''));$url=safe_external_url((string)($_POST['url']??''));$type=($_POST['link_type']??'link')==='video'?'video':'link';if($title===''||!$url)throw new \RuntimeException('Enter a title and a valid HTTP/HTTPS URL.');$pdo->prepare('INSERT INTO lesson_links (lesson_id,title,url,link_type,created_at) VALUES (?,?,?,?,?)')->execute([$id,$title,$url,$type,gmdate('Y-m-d H:i:s')]);$message='External resource added.';
                }elseif($action==='delete_link'&&$canManage){$pdo->prepare('DELETE FROM lesson_links WHERE id=? AND lesson_id=?')->execute([(int)($_POST['link_id']??0),$id]);$message='External resource removed.';
                }elseif($action==='set_prerequisites'&&$canManage){self::savePrerequisites($pdo,$lesson,$course,array_map('intval',(array)($_POST['prerequisites']??[])));$message='Prerequisites updated.';
                }elseif($action==='set_progress'&&!$canManage){$complete=isset($_POST['completed']);self::saveProgress($pdo,(int)$user['id'],$id,$complete?100:0);$message=$complete?'Lesson marked complete.':'Lesson marked incomplete.';
                }elseif($action!=='')$error='You do not have permission for that action.';
            }catch(\Throwable $e){$error=self::friendlyDbError($e,'Unable to update lesson.');}}
        }

        $materials=self::materials($pdo,$id);$links=self::links($pdo,$id);$prereqIds=self::prerequisiteIds($pdo,$id);$courseLessons=self::allLessonsForCourse($pdo,(int)$course['id']);$progress=self::lessonProgress($pdo,(int)$user['id'],$id);[$previous,$next]=self::neighborLessons($pdo,$courseLessons,$id,$user,$canManage);
        ob_start(); ?>
        <div class="crumbs"><a href="<?= e(app_url('?r=subjects')) ?>">Subjects</a><span>›</span><a href="<?= e(app_url('?r=subject&id='.(int)$course['subject_id'])) ?>"><?= e($course['subject_name']) ?></a><span>›</span><a href="<?= e(app_url('?r=course&id='.(int)$course['id'])) ?>"><?= e($course['title']) ?></a><span>›</span><span><?= e($lesson['title']) ?></span></div>
        <?php if($message): ?><div class="alert alert-success"><?= e($message) ?></div><?php endif; ?><?php if($error): ?><div class="alert alert-danger"><?= e($error) ?></div><?php endif; ?>
        <div class="lesson-view-grid"><article class="card lesson-content"><header><span class="badge <?= $lesson['status']==='published'?'badge-ok':'' ?>"><?= e($lesson['status']) ?></span><h1><?= e($lesson['title']) ?></h1><div class="lesson-meta"><?php if($lesson['duration_minutes']): ?><span><?= (int)$lesson['duration_minutes'] ?> min</span><?php endif; ?><?php if($lesson['release_at']): ?><span>Release <?= e($lesson['release_at']) ?> UTC</span><?php endif; ?></div></header>
          <?php if($lesson['objectives']): ?><section class="lesson-callout"><h2>Learning objectives</h2><p><?= nl2br(e($lesson['objectives'])) ?></p></section><?php endif; ?>
          <div class="rich-content"><?= $lesson['content'] ?: '<p class="muted">No lesson content yet.</p>' ?></div>
          <?php if($lesson['instructions']): ?><section class="lesson-callout"><h2>Instructions</h2><p><?= nl2br(e($lesson['instructions'])) ?></p></section><?php endif; ?>
          <?php foreach($links as $link): ?><?php $embed=$link['link_type']==='video'?lesson_embed_url($link['url']):null; ?><?php if($embed): ?><section class="video-card"><h2><?= e($link['title']) ?></h2><div class="video-frame"><iframe src="<?= e($embed) ?>" title="<?= e($link['title']) ?>" loading="lazy" allow="accelerometer; encrypted-media; picture-in-picture" allowfullscreen referrerpolicy="strict-origin-when-cross-origin"></iframe></div></section><?php elseif($link['link_type']==='video' && preg_match('/\.mp4(?:\?.*)?$/i',$link['url'])): ?><section class="video-card"><h2><?= e($link['title']) ?></h2><video controls preload="metadata" src="<?= e($link['url']) ?>"></video></section><?php endif; ?><?php endforeach; ?>
          <?php if($materials||$links): ?><section class="resource-section"><h2>Resources</h2><div class="resource-list"><?php foreach($materials as $m): ?><div><span class="file-icon">↓</span><span><strong><?= e($m['original_name']) ?></strong><small><?= e($m['mime_type']) ?> · <?= e(self::humanBytes((int)$m['size_bytes'])) ?></small></span><a class="btn btn-small" href="<?= e(app_url('?r=material-download&id='.(int)$m['id'])) ?>">Download</a><?php if($canManage): ?><form method="post" class="inline-form" onsubmit="return confirm('Remove this material?')"><input type="hidden" name="_csrf" value="<?= e(Csrf::token()) ?>"><input type="hidden" name="action" value="delete_material"><input type="hidden" name="material_id" value="<?= (int)$m['id'] ?>"><button class="icon-btn danger">×</button></form><?php endif; ?></div><?php endforeach; ?><?php foreach($links as $l): ?><div><span class="file-icon">↗</span><span><strong><?= e($l['title']) ?></strong><small><?= e(ucfirst($l['link_type'])) ?></small></span><a class="btn btn-small" href="<?= e($l['url']) ?>" target="_blank" rel="noopener noreferrer">Open</a><?php if($canManage): ?><form method="post" class="inline-form"><input type="hidden" name="_csrf" value="<?= e(Csrf::token()) ?>"><input type="hidden" name="action" value="delete_link"><input type="hidden" name="link_id" value="<?= (int)$l['id'] ?>"><button class="icon-btn danger">×</button></form><?php endif; ?></div><?php endforeach; ?></div></section><?php endif; ?>
          <?php if(!$canManage): ?><form method="post" class="completion-card"><input type="hidden" name="_csrf" value="<?= e(Csrf::token()) ?>"><input type="hidden" name="action" value="set_progress"><label class="completion-check"><input type="checkbox" name="completed" value="1" <?= $progress===100?'checked':'' ?> onchange="this.form.submit()"><span><?= $progress===100?'Completed':'Mark lesson complete' ?></span></label></form><?php endif; ?>
          <nav class="lesson-nav"><?php if($previous): ?><a class="btn" href="<?= e(app_url('?r=lesson&id='.(int)$previous['id'])) ?>">← <?= e($previous['title']) ?></a><?php else: ?><span></span><?php endif; ?><?php if($next): ?><a class="btn btn-primary" href="<?= e(app_url('?r=lesson&id='.(int)$next['id'])) ?>"><?= e($next['title']) ?> →</a><?php endif; ?></nav>
        </article>

        <?php if($canManage): ?><aside class="lesson-editor-stack"><section class="card"><h2>Edit lesson</h2><form method="post"><input type="hidden" name="_csrf" value="<?= e(Csrf::token()) ?>"><input type="hidden" name="action" value="update_lesson"><label>Title<input name="title" value="<?= e($lesson['title']) ?>" required maxlength="180"></label><label>Content <small>Use the toolbar for safe formatted text.</small><div class="editor-toolbar"><button type="button" data-editor-command="bold"><strong>B</strong></button><button type="button" data-editor-command="italic"><em>I</em></button><button type="button" data-editor-command="insertUnorderedList">• List</button><button type="button" data-editor-block="h2">H2</button><button type="button" data-editor-block="p">P</button></div><div class="rich-editor" contenteditable="true" data-rich-editor><?= $lesson['content'] ?></div><textarea name="content" data-rich-input hidden><?= e($lesson['content']) ?></textarea></label><label>Learning objectives<textarea name="objectives" rows="3"><?= e($lesson['objectives']) ?></textarea></label><label>Instructions<textarea name="instructions" rows="3"><?= e($lesson['instructions']) ?></textarea></label><div class="form-row"><label>Duration (minutes)<input type="number" name="duration_minutes" min="1" max="1440" value="<?= e($lesson['duration_minutes']) ?>"></label><label>Release at (UTC)<input type="datetime-local" name="release_at" value="<?= e(datetime_input_value($lesson['release_at'])) ?>"></label></div><label>Status<select name="status"><?php foreach(['draft','published','archived'] as $st): ?><option value="<?= $st ?>" <?= $lesson['status']===$st?'selected':'' ?>><?= ucfirst($st) ?></option><?php endforeach; ?></select></label><button class="btn btn-primary">Save lesson</button></form></section>
          <section class="card"><h2>Upload material</h2><p class="hint">Private download only. Executable files are rejected; server MIME type and file signatures are checked.</p><form method="post" enctype="multipart/form-data"><input type="hidden" name="_csrf" value="<?= e(Csrf::token()) ?>"><input type="hidden" name="action" value="upload_material"><label>File<input type="file" name="material" required accept=".pdf,.doc,.docx,.ppt,.pptx,.jpg,.jpeg,.png,.webp,.mp4,.zip"></label><button class="btn">Upload</button></form></section>
          <section class="card"><h2>External resource</h2><form method="post"><input type="hidden" name="_csrf" value="<?= e(Csrf::token()) ?>"><input type="hidden" name="action" value="add_link"><label>Title<input name="title" required maxlength="180"></label><label>URL<input name="url" type="url" required></label><label>Type<select name="link_type"><option value="link">Link</option><option value="video">Video</option></select></label><button class="btn">Add resource</button></form></section>
          <section class="card"><h2>Prerequisites</h2><form method="post"><input type="hidden" name="_csrf" value="<?= e(Csrf::token()) ?>"><input type="hidden" name="action" value="set_prerequisites"><div class="checkbox-list"><?php foreach($courseLessons as $l): ?><?php if((int)$l['id']===$id)continue; ?><label><input type="checkbox" name="prerequisites[]" value="<?= (int)$l['id'] ?>" <?= in_array((int)$l['id'],$prereqIds,true)?'checked':'' ?>><span><?= e($l['section_title'].' · '.$l['title']) ?></span></label><?php endforeach; ?></div><button class="btn">Save prerequisites</button></form></section>
        </aside><?php endif; ?></div>
        <?php render_page($lesson['title'],ob_get_clean());
    }

    public static function download(): void
    {
        Auth::requireAuth();$pdo=Database::connection();$user=Auth::user();$id=(int)($_GET['id']??0);
        $stmt=$pdo->prepare('SELECT m.*,l.status lesson_status,l.release_at,cs.course_id,c.teacher_id,c.status course_status,c.subject_id FROM learning_materials m INNER JOIN lessons l ON l.id=m.lesson_id INNER JOIN course_sections cs ON cs.id=l.course_section_id INNER JOIN courses c ON c.id=cs.course_id WHERE m.id=? LIMIT 1');$stmt->execute([$id]);$m=$stmt->fetch();if(!$m)self::notFoundOrDenied();
        $course=self::loadCourse($pdo,(int)$m['course_id']);if(!$course||!CoursePolicy::canViewCourse($course,$user))self::notFoundOrDenied();
        if(!CoursePolicy::canManage($course,$user)){ $lesson=self::loadLesson($pdo,(int)$m['lesson_id']);if(!$lesson||!CoursePolicy::lessonAvailableForStudent($lesson,(int)$user['id']))self::notFoundOrDenied(); }
        $path=UploadService::resolveStoredPath((string)$m['stored_name']);if(!$path||!is_file($path)){http_response_code(404);echo 'File not found.';return;}
        $name=preg_replace('/[\r\n"]+/','_', (string)$m['original_name']);header('Content-Type: application/octet-stream');header('X-Content-Type-Options: nosniff');header('Content-Disposition: attachment; filename="'.addcslashes($name,'"\\').'"');header('Content-Length: '.filesize($path));header('Cache-Control: private, no-store');readfile($path);exit;
    }
}
